            Instant.now().plusSeconds(120));
        assertThat(jobs.bindUpload(job, "test-bucket", key, "version", Instant.now())).isTrue();
        return job;
    }

    private int count(String table) {
        return jdbc.sql("SELECT count(*) FROM " + table).query(Integer.class).single();
    }
